using sv_70e67d95fca9442e9a52d0ae93b3a28c.Client.Services;

namespace sv_70e67d95fca9442e9a52d0ae93b3a28c.Services;

/// <summary>
/// Server-side implementation that simulates a slow backend with seeded data.
/// </summary>
public sealed class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new ShipmentDetails(
            TrackingNumber: "TRK-001",
            Status: "In Transit",
            Location: "Chicago, IL",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 20, 17, 0, 0, TimeSpan.FromHours(-5)),
            StatusUpdates:
            [
                new StatusUpdate(new DateTimeOffset(2026, 6, 14, 9, 0, 0, TimeSpan.FromHours(-5)), "Package picked up"),
                new StatusUpdate(new DateTimeOffset(2026, 6, 15, 14, 30, 0, TimeSpan.FromHours(-5)), "Arrived at sorting facility"),
                new StatusUpdate(new DateTimeOffset(2026, 6, 16, 8, 15, 0, TimeSpan.FromHours(-5)), "Departed sorting facility — en route to Chicago"),
            ]),

        ["TRK-002"] = new ShipmentDetails(
            TrackingNumber: "TRK-002",
            Status: "Delivered",
            Location: "Austin, TX",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 15, 12, 0, 0, TimeSpan.FromHours(-5)),
            StatusUpdates:
            [
                new StatusUpdate(new DateTimeOffset(2026, 6, 12, 10, 0, 0, TimeSpan.FromHours(-5)), "Package picked up"),
                new StatusUpdate(new DateTimeOffset(2026, 6, 13, 16, 0, 0, TimeSpan.FromHours(-5)), "In transit"),
                new StatusUpdate(new DateTimeOffset(2026, 6, 14, 11, 45, 0, TimeSpan.FromHours(-5)), "Out for delivery"),
                new StatusUpdate(new DateTimeOffset(2026, 6, 14, 14, 20, 0, TimeSpan.FromHours(-5)), "Delivered — signed by J. Smith"),
            ]),

        ["TRK-003"] = new ShipmentDetails(
            TrackingNumber: "TRK-003",
            Status: "Processing",
            Location: "Seattle, WA",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 25, 18, 0, 0, TimeSpan.FromHours(-7)),
            StatusUpdates:
            [
                new StatusUpdate(new DateTimeOffset(2026, 6, 17, 7, 0, 0, TimeSpan.FromHours(-7)), "Order received — preparing shipment"),
            ]),
    };

    public async Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"No shipment found for tracking number '{trackingNumber}'.");
    }
}

